async ({ git: { status, fetch, switchBranch, log } }) => {
  const before = (await status(["--short", "--branch"])).stdout;
  await fetch(["origin", "durable-collapse-finished-runs"]);
  const sw = await switchBranch(["durable-collapse-finished-runs"]);
  const after = (await status(["--short", "--branch"])).stdout;
  const l = (await log(["--oneline", "-3"])).stdout;
